export type DshIconName = keyof typeof SHAPES

export function DshIcon({ name, size = 16, className }: { name: DshIconName; size?: number; className?: string }): ReactElement {
  const shape = SHAPES[name]
  if (shape === undefined) return <span aria-hidden="true" />
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      viewBox={shape.viewBox}
      className={className === undefined ? 'blg-dsh-icon' : `blg-dsh-icon ${className}`}
      aria-hidden="true"
      style={{ verticalAlign: '-0.15em', flex: 'none' }}
      dangerouslySetInnerHTML={{ __html: shape.body }}
    />
  )
}
